/* Beginner explanations use only the player's cards and the public board. */
(function(root){
const stages=[
['Две карты — начало раздачи','Префлоп','Две карты внизу стола — ваши: соперники их не видят. J — валет, Q — дама, K — король, A — туз. Пять мест в центре — для общих карт. Цель — собрать лучшие пять карт из своих и общих: можно использовать обе свои карты, одну или ни одной.','Блайнды 10 и 20 — обязательные ставки двух игроков, чтобы в банке сразу были фишки. Банк — все фишки, поставленные в этой раздаче.'],
['На столе три общие карты','Флоп','Эти три карты доступны всем. Вместе с вашими двумя картами они уже дают комбинацию из пяти карт. После флопа откроются ещё две общие карты — по одной.','Начался новый круг ставок. Если никто ещё не поставил, можно сказать «чек» и остаться в игре бесплатно.'],
['Открылась четвёртая общая карта','Тёрн','Теперь вам доступны шесть карт: две свои и четыре общие. Из них засчитываются только лучшие пять. Осталась одна общая карта, и комбинация ещё может измениться.','Ставки прошлых кругов уже лежат в банке. Суммы перед игроками — их ставки только в текущем круге.'],
['Последняя общая карта','Ривер','Все пять общих карт открыты. Новых карт больше не будет. После последнего круга ставок оставшиеся игроки откроют руки, и лучшие пять карт определят победителя.','Если все соперники сбросят карты, оставшийся игрок заберёт банк без вскрытия — даже со слабой рукой.']
];
const ranks={2:'двойки',3:'тройки',4:'четвёрки',5:'пятёрки',6:'шестёрки',7:'семёрки',8:'восьмёрки',9:'девятки',10:'десятки',11:'валеты',12:'дамы',13:'короли',14:'тузы'};
const faces=r=>({11:'J',12:'Q',13:'K',14:'A'}[r]||String(r));
function bestFive(cards){if(cards.length<5)return[];let best=[],score=null;function visit(start,picked){if(picked.length===5){const s=Poker.evaluate5(picked);if(!score||Poker.compare(s,score)>0){score=s;best=picked.slice();}return;}for(let i=start;i<=cards.length-(5-picked.length);i++)visit(i+1,[...picked,cards[i]]);}visit(0,[]);return best.sort((a,b)=>b.r-a.r);}
function describe(cards){if(cards.length<5){return cards.length===2&&cards[0].r===cards[1].r?'Карманная пара: '+ranks[cards[0].r]+'.':'Пока у вас две отдельные карты. Полная комбинация появится на флопе.';}const s=Poker.evaluate(cards);const details=[()=> 'Пары нет: сравнивается старшая карта '+faces(s[1])+', затем следующие по старшинству.',()=> 'Две карты одного ранга: '+ranks[s[1]]+'. Остальные три карты — кикеры: они решают спор при равных парах.',()=> 'Две разные пары: '+ranks[s[1]]+' и '+ranks[s[2]]+'.',()=> 'Три карты одного ранга: '+ranks[s[1]]+'.',()=> 'Пять карт по порядку, со старшей '+faces(s[1])+'. Масти могут отличаться.',()=> 'Пять карт одной масти. Порядок рангов не важен.',()=> 'Три карты одного ранга ('+ranks[s[1]]+') и пара ('+ranks[s[2]]+').',()=> 'Четыре карты одного ранга: '+ranks[s[1]]+'.',()=> 'Пять последовательных карт одной масти.'];return Poker.HANDS[s[0]]+'. '+details[s[0]]();}
function advice(g){const p=g.players[0];if(g.done||g.turn!==0||p.folded)return null;const l=g.legal();if(!l.call)return{type:'call',title:'Можно сделать чек',text:'За продолжение платить не нужно. Для начала нажмите «Чек»: вы сохраните фишки и увидите, что сделают соперники.'};let strong=false;if(g.board.length<3){const [a,b]=p.cards;strong=(a.r===b.r&&a.r>=10)||(a.r>=11&&b.r>=11);}else{let s=Poker.evaluate([...p.cards,...g.board]);const common=g.board.length===5?Poker.evaluate(g.board):null;strong=s[0]>=2&&(!common||Poker.compare(s,common)>0);}const affordable=l.callAmount<=Math.max(20,Math.floor(p.stack*.12));if(strong&&affordable)return{type:'call',title:'Для начала — колл '+l.callAmount,text:'У вас неплохая основа для продолжения, а доплата относительно стека небольшая. Колл уравняет ставку. Более сильная рука у соперника всё ещё возможна.'};return{type:'fold',title:'Осторожный вариант — пас',text:'Чтобы продолжить, нужно заплатить '+l.callAmount+'. Для новичка с этой рукой проще сберечь фишки. Пас завершит ваше участие только в этой раздаче. Это упрощённый совет, а не расчёт шансов.'};}
function outcome(g){const p=g.players[0];let text;if(!g.showdown){const survivor=g.players.find(q=>!q.folded);text=survivor.name+' забирает банк: все остальные сбросили карты. Сила комбинации здесь не сравнивалась.';}else{const active=g.players.filter(q=>!q.folded);text=active.map(q=>q.name+': '+describe([...q.cards,...g.board])).join(' ');text+=' Сначала сравнивают тип комбинации, затем ранги внутри неё и кикеры. Полностью равные руки делят банк.';}if(p.folded)text+=' Вы сделали пас и больше не претендовали на банк.';const received=g.results.filter(r=>r.index===0).reduce((a,r)=>a+r.amount,0),net=received-p.total;text+=' Ваш итог за раздачу: '+(net>0?'+':'')+net+' фишек (получено '+received+', вложено '+p.total+').';if(g.results.length>1)text+=' При разных суммах олл-ина каждый банк разыгрывается отдельно; лишняя неуравненная ставка возвращается.';return text;}
const api={stages,bestFive,describe,advice,outcome};root.PokerCoach=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
